class Solution {
public:
    bool hasValidPath(std::vector<std::vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        if ((m + n - 1) % 2 != 0 || grid[0][0] == ')' || grid[m - 1][n - 1] == '(') return false;
        int maxBal = (m + n) / 2;
        std::vector<std::vector<std::vector<bool>>> vis(m, std::vector<std::vector<bool>>(n, std::vector<bool>(maxBal + 2, false)));
        vis[0][0][1] = true;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                for (int b = 0; b <= maxBal; ++b) {
                    if (!vis[r][c][b]) continue;
                    if (r + 1 < m) {
                        int nb = b + (grid[r + 1][c] == '(' ? 1 : -1);
                        if (nb >= 0 && nb <= maxBal) vis[r + 1][c][nb] = true;
                    }
                    if (c + 1 < n) {
                        int nb = b + (grid[r][c + 1] == '(' ? 1 : -1);
                        if (nb >= 0 && nb <= maxBal) vis[r][c + 1][nb] = true;
                    }
                }
            }
        }
        return vis[m - 1][n - 1][0];
    }
};

