var hasValidPath = function(grid) {
    const m = grid.length, n = grid[0].length;
    if ((m + n - 1) % 2 !== 0 || grid[0][0] === ')' || grid[m - 1][n - 1] === '(') return false;
    const maxBal = Math.floor((m + n) / 2);
    const vis = Array.from({ length: m }, () =>
        Array.from({ length: n }, () => new Uint8Array(maxBal + 2))
    );
    vis[0][0][1] = 1;
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            for (let b = 0; b <= maxBal; b++) {
                if (!vis[r][c][b]) continue;
                if (r + 1 < m) {
                    const nb = b + (grid[r + 1][c] === '(' ? 1 : -1);
                    if (nb >= 0 && nb <= maxBal) vis[r + 1][c][nb] = 1;
                }
                if (c + 1 < n) {
                    const nb = b + (grid[r][c + 1] === '(' ? 1 : -1);
                    if (nb >= 0 && nb <= maxBal) vis[r][c + 1][nb] = 1;
                }
            }
        }
    }
    return vis[m - 1][n - 1][0] === 1;
